#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sdb.h"

/* Declare internal functions */
extern void sdb_ns_free(Sdb *s);

int main(void) {
    Sdb *parent, *child;
    int i;

    parent = sdb_new0();
    child = sdb_new0();

    printf("Initial: parent=%p child=%p\n", (void*)parent, (void*)child);
    printf("parent->refs=%d child->refs=%d\n", parent->refs, child->refs);

    /* parent has THREE namespaces pointing to child */
    sdb_ns_set(parent, "ns1", child);
    printf("After ns1: child->refs=%d\n", child->refs);
    sdb_ns_set(parent, "ns2", child);
    printf("After ns2: child->refs=%d\n", child->refs);
    sdb_ns_set(parent, "ns3", child);
    printf("After ns3: child->refs=%d\n", child->refs);

    printf("\nCalling sdb_ns_free(parent)...\n");
    fflush(stdout);

    sdb_ns_free(parent);

    printf("After sdb_ns_free: parent->ns=%p\n", (void*)parent->ns);
    printf("child->refs=%d\n", child->refs);

    printf("\nCalling sdb_free(parent)...\n");
    fflush(stdout);

    sdb_free(parent);

    printf("Done\n");
    return 0;
}
EOF
